    register PixelInfo *tile_pixel;
    register unsigned int y;

    if (inDocInfo->image_type == GIMP_GRAY)
    {
        if (AllocateImagePixels(tile_image, exception) == MagickFalse)
            return MagickFalse;

        tile_pixel = tile_image->pixels;
        for (y = 0; y < (unsigned int) tile_image->rows; y++)
        {
            register unsigned int x;

            for (x = 0; x < (unsigned int) tile_image->columns; x++)
