                register unsigned char pixel;

                if (ReadBlobByte(image, &pixel) != MagickTrue)
                    return MagickFalse;

                tile_pixel->gray = (double) ScaleCharToQuantum(pixel);
                tile_pixel->opacity = (double) ScaleCharToQuantum(inLayerInfo->alpha);
                tile_pixel++;
            }
        }
    }
    else
    {
        if (AllocateImagePixels(tile_image, exception) == MagickFalse)
            return MagickFalse;

        tile_pixel = tile_image->pixels;
        for (y = 0; y < (unsigned int) tile_image->rows; y++)
        {
            register unsigned int x;

            for (x = 0; x < (unsigned int) tile_image->columns; x++)
            {
                register unsigned char red, green, blue;

                if (ReadBlobByte(image, &red) != MagickTrue)
                    return MagickFalse;

                if (ReadBlobByte(image, &green) != MagickTrue)
                    return MagickFalse;

                if (ReadBlobByte(image, &blue) != MagickTrue)
                    return MagickFalse;

                tile_pixel->red = (double) ScaleCharToQuantum(red);
