                tile_pixel++;
            }
        }
    }
    return MagickTrue;
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register PixelInfo *magick_restrict q;
    unsigned char *pixel_data;
    size_t number_pixels;
    size_t pixel_size;
    ssize_t x;
    ssize_t y;

    number_pixels = (size_t) tile_image->columns * tile_image->rows;
    pixel_size = sizeof(*pixel_data) * number_pixels;

    pixel_data = (unsigned char *) AcquireMemory(pixel_size);
    if (pixel_data == (unsigned char *) NULL)
        ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", tile_image->filename);

    /* Read pixel data from source image */
    for (y = 0; y < (ssize_t) tile_image->rows; y++) {
        q = AcquireAuthenticPixels(tile_image, 0, y, tile_image->columns, 1, exception);
        if (q == (PixelInfo *) NULL)
            return MagickFalse;

        for (x = 0; x < (ssize_t) tile_image->columns; x++) {
            if (inDocInfo->image_type == GIMP_GRAY) {
                /* Process grayscale pixel */
                unsigned char gray_value = pixel_data[y * tile_image->columns + x];
                SetPixelRed(q, gray_value);
                SetPixelGreen(q, gray_value);
                SetPixelBlue(q, gray_value);
                SetPixelAlpha(q, (Quantum) inLayerInfo->alpha);
            }
            else if (inDocInfo->image_type == GIMP_RGB) {
                /* Process RGB pixel */
                unsigned char red = pixel_data[3 * (y * tile_image->columns + x) + 0];
                unsigned char green = pixel_data[3 * (y * tile_image->columns + x) + 1];
                unsigned char blue = pixel_data[3 * (y * tile_image->columns + x) + 2];
                SetPixelRed(q, red);
                SetPixelGreen(q, green);
                SetPixelBlue(q, blue);
                SetPixelAlpha(q, (Quantum) inLayerInfo->alpha);
            }
            q++;
        }

        if (!UpdatePixelCache(tile_image))
            return MagickFalse;
    }

    RelinquishMemory(pixel_data);
    return MagickTrue;
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register ssize_t x;
    Quantum *q;
    ssize_t y;
    size_t width, height;
    unsigned char *pixel_data;

    width = tile_image->columns;
    height = tile_image->rows;

    pixel_data = (unsigned char *) AcquireMemory(data_length);
    if (pixel_data == (unsigned char *) NULL)
        return MagickFalse;

    /* Read pixel data from source image (placeholder for actual implementation) */
    if (!ReadPixelData(image, pixel_data, data_length, exception)) {
        RelinquishMemory(pixel_data);
        return MagickFalse;
    }

    for (y = 0; y < (ssize_t) height; y++) {
        q = QueueAuthenticPixels(tile_image, 0, y, width, 1, exception);
        if (q == (Quantum *) NULL)
            break;

        for (x = 0; (size_t) x < width; x++) {
            switch (inDocInfo->image_type) {
                case GIMP_GRAY:
                    {
                        Quantum gray;
                        gray = pixel_data[x];
                        q[0] = gray;
                        break;
                    }
                case GIMP_RGB:
                    {
                        Quantum red, green, blue;
                        red = pixel_data[x * 3 + 0];
                        green = pixel_data[x * 3 + 1];
                        blue = pixel_data[x * 3 + 2];
                        q[0] = red;
                        q[1] = green;
                        q[2] = blue;
                        break;
                    }
                default:
                    break;
            }
            if (inLayerInfo->has_alpha)
                q[3] = inLayerInfo->alpha_values[x];
            q += GetPixelChannels(tile_image);
        }
    }

    SyncAuthenticPixels(tile_image, exception);
    RelinquishMemory(pixel_data);

    if (y < (ssize_t) height)
        return MagickFalse;

    return MagickTrue;
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
  register PixelInfo
    *q;

  q = (PixelInfo *) AcquirePixelCache(tile_image, 0, 0, 1, 1, &exception);

  if (q == (PixelInfo *) NULL)
    return MagickFalse;

  if (inDocInfo->image_type == GIMP_GRAY)
  {
    for (size_t i = 0; i < data_length; i++)
    {
      q->red = q->green = q->blue = (MagickRealType) (image->pixels[i] / 255.0);
      q++;
    }
  }
  else if (inDocInfo->image_type == GIMP_RGB)
  {
    for (size_t i = 0; i < data_length; i += 3)
    {
      q->red = (MagickRealType) (image->pixels[i] / 255.0);
      q->green = (MagickRealType) (image->pixels[i + 1] / 255.0);
      q->blue = (MagickRealType) (image->pixels[i + 2] / 255.0);
      q++;
    }
  }
  else
  {
    ThrowBinaryException(OptionError, "UnknownImageType", image->filename);
    return MagickFalse;
  }

  (void) SyncPixelCache(tile_image, &exception);

  return MagickTrue;
}

MagickBooleanType LoadTileImage(Image *image, Image *tile_image, XCFDocInfo *inDocInfo, XCFLayerInfo *inLayerInfo, size_t data_length, ExceptionInfo *exception) {
    register ssize_t x;
    register PixelIntent pixelIntent;
    Quantum *q;
    ssize_t y;

    pixelIntent = GetPixelIntent(image);
    for (y = 0; y < (ssize_t) tile_image->rows; y++) {
        q = QueueAuthenticPixels(tile_image, 0, y, tile_image->columns, 1, exception);
        if (q == (Quantum *) NULL)
            return MagickFalse;

        switch (inDocInfo->image_type) {
            case GIMP_GRAY:
                for (x = 0; x < (ssize_t) tile_image->columns; x++) {
                    *q = GetPixelGray(image, x, y);
                    q += GetPixelChannels(tile_image);
                }
                break;
            case GIMP_RGB:
                for (x = 0; x < (ssize_t) tile_image->columns; x++) {
                    *q = GetPixelRed(image, x, y);
                    q++;
                    *q = GetPixelGreen(image, x, y);
                    q++;
                    *q = GetPixelBlue(image, x, y);
                    q++;
                }
                break;
            default:
                break;
        }
    }

    return MagickTrue;
}
